import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import express, { Request, Response } from 'express';
import multer from 'multer';
import pdfParse from 'pdf-parse';

const upload = multer({ 
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 } // 5MB limit
});

export const resumeRouter = express.Router();

resumeRouter.post('/api/parse-resume', upload.single('resume'), async (req: Request, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF file uploaded.' });
      return;
    }

    const parsedPdf = await pdfParse(req.file.buffer);
    const extractedText = parsedPdf.text;

    res.status(200).json({ 
      success: true, 
      fileName: req.file.originalname,
      textLength: extractedText.length,
      extractedText 
    });
  } catch (error) {
    console.error('PDF Parsing Error:', error);
    res.status(500).json({ error: 'Failed to parse PDF document.' });
  }
});

import React from 'react';

interface MatchScoreDialProps {
  score: number;
}

export const MatchScoreDial: React.FC<MatchScoreDialProps> = ({ score }) => {
  const radius = 45;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (score / 100) * circumference;

  const getColor = (s: number) => {
    if (s >= 80) return 'text-emerald-500 stroke-emerald-500';
    if (s >= 50) return 'text-amber-500 stroke-amber-500';
    return 'text-rose-500 stroke-rose-500';
  };

  return (
    <div className="flex flex-col items-center justify-center p-6 bg-slate-900 rounded-2xl shadow-xl border border-slate-800">
      <div className="relative flex items-center justify-center">
        <svg className="w-36 h-36 transform -rotate-90">
          <circle
            cx="72"
            cy="72"
            r={radius}
            stroke="currentColor"
            strokeWidth="10"
            className="text-slate-800 fill-none"
          />
          <circle
            cx="72"
            cy="72"
            r={radius}
            stroke="currentColor"
            strokeWidth="10"
            strokeDasharray={circumference}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            className={`fill-none transition-all duration-1000 ease-out ${getColor(score)}`}
          />
        </svg>
        <div className="absolute flex flex-col items-center">
          <span className={`text-3xl font-extrabold ${getColor(score).split(' ')[0]}`}>
            {score}%
          </span>
          <span className="text-xs text-slate-400 font-medium uppercase tracking-wider">Match Score</span>
        </div>
      </div>
    </div>
  );
};
